package tn.esprit.autoloc.service.impl;

import jakarta.persistence.EntityNotFoundException;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Service;
import tn.esprit.autoloc.domain.Employe;
import tn.esprit.autoloc.repository.EmployeRepository;
import tn.esprit.autoloc.service.interfaces.IEmployeService;

import java.util.List;

@Service
@RequiredArgsConstructor
public class EmployeServiceImpl implements IEmployeService {

    // Injected by Spring (constructor injection, generated by Lombok)
    private final EmployeRepository repository;

    @Override
    public List<Employe> retrieveAllEmployes() {
        return repository.findAll();
    }

    @Override
    public Employe retrieveEmploye(Long id) {
        return repository.findById(id)
                .orElseThrow(() -> new EntityNotFoundException("Employe not found with id " + id));
    }

    @Override
    public Employe addEmploye(Employe entity) {
        return repository.save(entity);
    }

    @Override
    public Employe modifyEmploye(Employe entity) {
        return repository.save(entity);
    }

    @Override
    public void removeEmploye(Long id) {
        repository.deleteById(id);
    }
}